import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { AnimatePresence, motion } from 'framer-motion';
import { ArrowDownRight, ArrowUpRight, ExternalLink, Github, X } from 'lucide-react';
import { portfolioData } from '../../data/portfolioData';
import { useLanguage } from '../../context/LanguageContext';
import { PageWrapper } from '../../shared/components/PageWrapper';
import { statsService } from '../../shared/services/statsService';
const Projects = () => {
  const { language } = useLanguage();
  const [selectedProject, setSelectedProject] = useState(null);
  const t = portfolioData.common[language];
  const copy = {
    fr: {
      eyebrow: 'Projets',
      title: 'Du travail concret, des idées en pratique.',
      intro: 'Une sélection de projets personnels et d’exercices réalisés pendant ma formation.',
      details: 'Détails du projet',
      close: 'Fermer',
      code: 'Voir le code',
      demo: 'Voir la démo'
    },
    en: {
      eyebrow: 'Projects',
      title: 'Practical work, ideas put to use.',
      intro: 'A selection of personal projects and exercises completed during my studies.',
      details: 'Project details',
      close: 'Close',
      code: 'View source',
      demo: 'Live demo'
    },
    ar: {
      eyebrow: 'المشاريع',
      title: 'أعمال عملية وأفكار قابلة للتطبيق.',
      intro: 'مجموعة من المشاريع الشخصية والتطبيقات المنجزة خلال التكوين.',
      details: 'تفاصيل المشروع',
      close: 'إغلاق',
      code: 'عرض الكود',
      demo: 'التجربة الحية'
    },
    es: {
      eyebrow: 'Proyectos',
      title: 'Trabajo práctico, ideas en acción.',
      intro: 'Una selección de proyectos personales y ejercicios realizados durante mi formación.',
      details: 'Detalles del proyecto',
      close: 'Cerrar',
      code: 'Ver código',
      demo: 'Ver demo'
    }
  }[language];
  const projects = portfolioData.projects;

  useEffect(() => {
    if (!selectedProject) return undefined;
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') setSelectedProject(null);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedProject]);

  const selectProject = (project) => {
    statsService.trackProjectClick();
    setSelectedProject(project);
  };

  return (
    <PageWrapper>
      <header className="max-w-3xl">
        <p className="eyebrow">{copy.eyebrow}</p>
        <h1 className="display-heading mt-3 text-4xl leading-tight sm:text-5xl">{copy.title}</h1>
        <p className="mt-4 max-w-2xl text-base leading-7 text-[var(--muted)]">{copy.intro}</p>
      </header>

      <div className="mt-8 grid gap-5 md:grid-cols-2">
        {projects.map((project, index) => (
          <motion.button
            key={project.id}
            type="button"
            layout
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            onClick={() => selectProject(project)}
            aria-label={`${copy.details}: ${project.title}`}
            className="group surface-card overflow-hidden text-start transition-colors hover:border-[var(--accent)]"
          >
            <div className={`project-visual ${project.visual || ''} aspect-[16/9]`} aria-hidden="true">
            </div>
            <div className="p-5 sm:p-6">
              <div className="flex items-start justify-between gap-4">
                <div>
                  <p className="text-xs font-medium text-[var(--muted)]">0{index + 1} · {project.category}</p>
                  <h2 className="mt-2 text-xl font-semibold">{project.title}</h2>
                </div>
                <ArrowUpRight size={19} className="mt-1 shrink-0 text-[var(--muted)] transition-colors group-hover:text-[var(--accent)]" />
              </div>
              <p className="mt-3 text-sm leading-6 text-[var(--muted)]">{project.description[language]}</p>
              <ul className="mt-4 flex flex-wrap gap-2">
                {project.tech.map((technology) => (
                  <li key={technology} className="rounded-full bg-[var(--accent-soft)] px-2.5 py-1 text-xs text-[var(--ink)]">{technology}</li>
                ))}
              </ul>
            </div>
          </motion.button>
        ))}
      </div>

      <AnimatePresence>
        {selectedProject && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setSelectedProject(null)}
            className="fixed inset-0 z-[100] flex items-center justify-center overflow-y-auto bg-black/70 p-3 sm:p-6"
          >
            <motion.section
              initial={{ opacity: 0, y: 12, scale: 0.99 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 8 }}
              onClick={(event) => event.stopPropagation()}
              role="dialog"
              aria-modal="true"
              aria-labelledby="project-dialog-title"
              className="relative my-auto grid w-full max-w-5xl overflow-hidden rounded-xl border border-[var(--line)] bg-[var(--surface)] md:grid-cols-[1.2fr_0.8fr]"
            >
              <button
                type="button"
                onClick={() => setSelectedProject(null)}
                aria-label={copy.close}
                className="absolute right-3 top-3 z-10 rounded-full bg-[var(--surface)] p-2 text-[var(--ink)] shadow-sm hover:text-[var(--accent)]"
              >
                <X size={20} />
              </button>
              <div className={`project-visual ${selectedProject.visual || ''} min-h-[260px]`}>
              </div>
              <div className="flex flex-col p-6 sm:p-8">
                <p className="eyebrow">{copy.details}</p>
                <h2 id="project-dialog-title" className="display-heading mt-3 text-3xl">{selectedProject.title}</h2>
                <p className="mt-4 text-sm leading-7 text-[var(--muted)]">{selectedProject.description[language]}</p>
                <h3 className="mt-7 text-xs font-semibold uppercase tracking-[0.1em] text-[var(--muted)]">{t.techStack}</h3>
                <ul className="mt-3 flex flex-wrap gap-2">
                  {selectedProject.tech.map((technology) => (
                    <li key={technology} className="rounded-full bg-[var(--accent-soft)] px-3 py-1.5 text-xs">{technology}</li>
                  ))}
                </ul>
                <div className="mt-auto flex flex-wrap gap-3 pt-8">
                  {selectedProject.github && (
                    <a href={selectedProject.github} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 rounded-md bg-[var(--ink)] px-4 py-2.5 text-sm font-medium text-[var(--page)] hover:bg-[var(--accent)]">
                      <Github size={16} />
                      {copy.code}
                      <ExternalLink size={14} />
                    </a>
                  )}
                  {selectedProject.demo && (
                    <a href={selectedProject.demo} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 rounded-md border border-[var(--line)] px-4 py-2.5 text-sm font-medium hover:border-[var(--accent)] hover:text-[var(--accent)]">
                      {copy.demo}
                      <ExternalLink size={14} />
                    </a>
                  )}
                </div>
              </div>
            </motion.section>
          </motion.div>
        )}
      </AnimatePresence>

      <Link to="/contact" className="mt-10 inline-flex items-center gap-2 text-sm font-semibold text-[var(--accent)] hover:underline">
        {portfolioData.profile[language].contactMe}
        <ArrowDownRight size={16} />
      </Link>
    </PageWrapper>
  );
};

export default Projects;
